async function (variables) {
	var g = new ReadOnlyDetailView(variables.element);
	g.title = function (data) { return "[resource_shortdisplayname[PurchaseORder]]" + kendo.htmlEncode(data.Number) + " [resource_shortdisplayname[from]]: " + kendo.htmlEncode(data.CreditorName) + " [resource_shortdisplayname[to]] " + kendo.htmlEncode(data.DebtorName) + ""; };
	g.fields = [
            { field: "Number" }, 
            { field: "DebtorState", template: function (data) { return "" + kendo.htmlEncode(B2B.transactionStates[data.DebtorState]) + ""; } }, 
		    { field: "SourceSystemId", title: "[resource_shortdisplayname[sourcesystemid]]", description: "[resource_description[sourcesystemid]]" },
            { field:"CreditorState", template: function (data) { return "" + kendo.htmlEncode(B2B.transactionStates[data.CreditorState]) + ""; } },  
            { field:"CreationDate", type: "date", format: type.dateFormat  }, 
            { field:"ReceivedDate", type: "date", format: type.dateFormat },  
            { field:"DueDate", type: "date", format: type.dateFormat },  
            { field:"LastUpdated", type: "date", format: type.dateFormat }, 
            { field:"TaxPoint", type: "date", format: type.dateFormat },
            { field:"ValueOfTax", type: "number", format: type.moneyFormat },  
            { field:"Value", type: "number", format: type.moneyFormat }
        ];
        g.splits = ["CreationDate"];
        g.toolbar = "<button onClick='javascript: history.go(-1)'><span class='k-icon k-i-arrow-parent'></span> [resource_shortdisplayname[back]]</button>";
        variables.PurchaseOrderDetails = g;
}
